# ============================================================
# TESTPLAN SHEET COLUMNS
# ============================================================
testplan_columns = [
    "Index",
    "SS / Module",
    "Feature",
    "Test Case Name",
    "Test Description",
    "Speed",
    "Mode",
    "Memory Start Offset",
    "Memory End Offset",
    "Remarks",
    "Test Steps / Procedure",
    "Impacted Registers",
    "Validation / Acceptance Criteria",
    "Code Generation"
]

# ============================================================
# METADATA SHEET COLUMNS
# ============================================================
metadata_columns = [
    "Index",
    "Test Case Name",
    "Meta Test Description",
    "Meta Test Steps / Procedure",
    "Meta Impacted Registers",
    "Meta Validation / Acceptance Criteria",
    "Meta Headers",
    "Meta Macros",
    "Meta Arrays"
]

# ============================================================
# CREATE WORKBOOK
# ============================================================
wb = openpyxl.Workbook()

# TestPlan sheet
ws_tp = wb.active
ws_tp.title = "TestPlan"

# MetaData sheet
ws_md = wb.create_sheet("MetaData")

# ============================================================
# FORMATTING
# ============================================================
header_font = Font(name='Calibri', bold=True, color='FFFFFF', size=11)
header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
wrap_alignment = Alignment(wrap_text=True, vertical='top')

# ============================================================
# POPULATE TESTPLAN SHEET
# ============================================================
for col_idx, col_name in enumerate(testplan_columns, 1):
    cell = ws_tp.cell(row=1, column=col_idx, value=col_name)
    cell.font = header_font
    cell.fill = header_fill
    cell.alignment = wrap_alignment

for row_idx, row_data in enumerate(json_data, 2):
    for col_idx, col_name in enumerate(testplan_columns, 1):
        if col_name == "Code Generation":
            value = ""
        else:
            value = row_data.get(col_name, "")
        cell = ws_tp.cell(row=row_idx, column=col_idx, value=value)
        cell.alignment = wrap_alignment

# ============================================================
# POPULATE METADATA SHEET
# ============================================================
for col_idx, col_name in enumerate(metadata_columns, 1):
    cell = ws_md.cell(row=1, column=col_idx, value=col_name)
    cell.font = header_font
    cell.fill = header_fill
    cell.alignment = wrap_alignment

for row_idx, row_data in enumerate(json_data, 2):
    for col_idx, col_name in enumerate(metadata_columns, 1):
        value = row_data.get(col_name, "")
        cell = ws_md.cell(row=row_idx, column=col_idx, value=value)
        cell.alignment = wrap_alignment

# ============================================================
# FREEZE PANES
# ============================================================
ws_tp.freeze_panes = 'A2'
ws_md.freeze_panes = 'A2'

# ============================================================
# AUTO-SIZE COLUMNS
# ============================================================
MAX_WIDTH = 60

for ws in [ws_tp, ws_md]:
    for col_cells in ws.columns:
        max_len = 0
        col_letter = get_column_letter(col_cells[0].column)
        for cell in col_cells:
            if cell.value:
                lines = str(cell.value).split('\n')
                for line in lines:
                    if len(line) > max_len:
                        max_len = len(line)
        adjusted = min(max_len + 2, MAX_WIDTH)
        if adjusted < 12:
            adjusted = 12
        ws.column_dimensions[col_letter].width = adjusted

# ============================================================
# SET METADATA SHEET TO VERY HIDDEN
# ============================================================
ws_md.sheet_state = 'veryHidden'

# ============================================================
# SAVE WORKBOOK
# ============================================================
wb.save(OUTPUT_PATH)
print(f"Workbook saved: {OUTPUT_PATH}")

# ============================================================
# POST-SAVE VALIDATION
# ============================================================
if not os.path.exists(OUTPUT_PATH):
    print("VALIDATION FAILED: File does not exist")
    sys.exit(1)

file_size = os.path.getsize(OUTPUT_PATH)
if file_size <= 0:
    print("VALIDATION FAILED: File size is 0")
    sys.exit(1)

print(f"File size: {file_size} bytes")

# Reopen and validate
wb2 = openpyxl.load_workbook(OUTPUT_PATH)
if "TestPlan" not in wb2.sheetnames:
    print("VALIDATION FAILED: TestPlan sheet missing")
    sys.exit(1)
if "MetaData" not in wb2.sheetnames:
    print("VALIDATION FAILED: MetaData sheet missing")
    sys.exit(1)

ws_tp2 = wb2["TestPlan"]
ws_md2 = wb2["MetaData"]

tp_rows = ws_tp2.max_row - 1
md_rows = ws_md2.max_row - 1

print(f"TestPlan rows: {tp_rows}")
print(f"MetaData rows: {md_rows}")

if tp_rows != 4:
    print(f"VALIDATION FAILED: Expected 4 TestPlan rows, got {tp_rows}")
    sys.exit(1)
if md_rows != 4:
    print(f"VALIDATION FAILED: Expected 4 MetaData rows, got {md_rows}")
    sys.exit(1)

# Validate MetaData content
meta_fields = ["Meta Test Description", "Meta Test Steps / Procedure", "Meta Impacted Registers",
               "Meta Validation / Acceptance Criteria", "Meta Headers", "Meta Macros", "Meta Arrays"]

validation_passed = True
for row_idx, row_data in enumerate(json_data):
    for field in meta_fields:
        col_idx = metadata_columns.index(field) + 1
        cell_value = ws_md2.cell(row=row_idx + 2, column=col_idx).value
        expected = row_data.get(field, "")
        if str(cell_value or "") != str(expected):
            print(f"VALIDATION FAILED: Row {row_idx+1}, Field '{field}' mismatch")
            validation_passed = False

if not validation_passed:
    print("METADATA VALIDATION FAILED")
    sys.exit(1)

print("ALL VALIDATIONS PASSED")
print(f"OUTPUT: {OUTPUT_PATH}")
wb2.close()
